    #: СЛОВА ОПЕРАТОРА и только они: по ним человек чинит доступ в кабинете оператора
    last_error: str
    #: Машинный код последней неудачи (docflow.edo.*); его переводит интерфейс
    last_error_code: str
    messages_total: int
    #: Сколько пакетов ждут нашего действия
    actions_due: int
    created_at: str
    updated_at: str

